/**
 * Compact, self-contained Markdown parser implementing the standard marked.parse API.
 * Safely parses common GitHub release markdown (headers, lists, bold, italics, code, links).
 */
(function (global) {
  function escapeHtml(str) {
    return str
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function parseInline(text) {
    let out = escapeHtml(text);
    // Inline code
    out = out.replace(/`([^`]+)`/g, "<code>$1</code>");
    // Bold
    out = out.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    // Italic
    out = out.replace(/\*([^*]+)\*/g, "<em>$1</em>");
    // Links
    out = out.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
    return out;
  }

  function parse(markdown) {
    if (!markdown) return "";
    const lines = markdown.replace(/\r\n/g, "\n").split("\n");
    let html = "";
    let inList = false;
    let inCode = false;
    let codeContent = "";

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Code blocks
      if (line.trim().startsWith("```")) {
        if (inCode) {
          html += "<pre><code>" + escapeHtml(codeContent.trim()) + "</code></pre>\n";
          codeContent = "";
          inCode = false;
        } else {
          if (inList) {
            html += "</ul>\n";
            inList = false;
          }
          inCode = true;
        }
        continue;
      }

      if (inCode) {
        codeContent += line + "\n";
        continue;
      }

      // Headers
      const headerMatch = line.match(/^(#{1,6})\s+(.*)$/);
      if (headerMatch) {
        if (inList) {
          html += "</ul>\n";
          inList = false;
        }
        const level = headerMatch[1].length;
        const text = parseInline(headerMatch[2]);
        html += `<h${level}>${text}</h${level}>\n`;
        continue;
      }

      // Unordered List items
      const listMatch = line.match(/^[-*]\s+(.*)$/);
      if (listMatch) {
        if (!inList) {
          html += "<ul>\n";
          inList = true;
        }
        html += `<li>${parseInline(listMatch[1])}</li>\n`;
        continue;
      } else if (inList && line.trim() === "") {
        html += "</ul>\n";
        inList = false;
      }

      // Plain paragraphs
      if (line.trim()) {
        if (inList) {
          html += "</ul>\n";
          inList = false;
        }
        html += `<p>${parseInline(line)}</p>\n`;
      }
    }

    if (inList) html += "</ul>\n";
    if (inCode) html += "<pre><code>" + escapeHtml(codeContent.trim()) + "</code></pre>\n";

    return html;
  }

  global.marked = { parse: parse };
})(typeof window !== "undefined" ? window : globalThis);
